package org.slavicmyths.guardians;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.network.syncher.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.*;
public final class SpringKeeper extends GuardianEntity {
 private static final EntityDataAccessor<Integer> VALVES=SynchedEntityData.defineId(SpringKeeper.class,EntityDataSerializers.INT);
 private static final EntityDataAccessor<org.joml.Vector3f> WHIRL_AT=SynchedEntityData.defineId(SpringKeeper.class,EntityDataSerializers.VECTOR3);
 private long whipReady,whirlReady,prisonReady,floodReady,healReady;
 private Vec3 whirl=Vec3.ZERO;private UUID prisonTarget,lastPrison;private WaterPrison prison;private final List<UUID> echoes=new ArrayList<>();
 public SpringKeeper(EntityType<? extends SpringKeeper> t,Level w){super(t,w,true);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder b){super.defineSynchedData(b);b.define(VALVES,0);b.define(WHIRL_AT,new org.joml.Vector3f());}
 public int valves(){return entityData.get(VALVES);}
 public Vec3 whirlCenter(){var p=entityData.get(WHIRL_AT);return new Vec3(origin().getX()+p.x,origin().getY()+p.y,origin().getZ()+p.z);}
 public boolean desperation(){return getHealth()<=getMaxHealth()*.3;}
 private CompoundTag record(){return GuardianLedger.get((ServerLevel)level()).row(instance);}
 @Override protected void combat(){var w=(ServerLevel)level();var d=GuardianLedger.get(w);var n=record();long now=w.getGameTime();valves(n,now);
  if(desperation()&&!n.getBoolean("EchoesCalled")){n.putBoolean("EchoesCalled",true);d.setDirty();for(int sign:new int[]{-1,1}){var echo=GuardianContent.ECHO.get().create(w);if(echo==null)continue;echo.configure(this);echo.setPos(position().add(sign*3,0,0));if(arena().contains(echo.position())&&w.noCollision(echo,echo.getBoundingBox())&&w.addFreshEntity(echo))echoes.add(echo.getUUID());}}
  int s=state(),a=age();if(s==GuardianRules.MELEE){meleeTick();return;}if(s==GuardianRules.INTERRUPTED){if(a>=GuardianRules.EXHAUST)state(GuardianRules.COMBAT);return;}
  if(s==GuardianRules.SEEK){var center=Vec3.atBottomCenterOf(net.minecraft.core.BlockPos.of(layout.getLong("SpawnAnchor")));getNavigation().moveTo(center.x,center.y,center.z,1);if(distanceToSqr(center)<4){state(GuardianRules.HEAL);sound("spring_heal_begin");}else if(a>GuardianRules.SEEK_LIMIT){healReady=now+GuardianRules.HEAL_COOLDOWN;state(GuardianRules.COMBAT);}return;}
  if(s==GuardianRules.HEAL){if(a%4==0)for(int role=0;role<2;role++){var from=Vec3.atCenterOf(GuardianWorld.valveAt(layout,role));for(int i=0;i<6;i++){var p=from.lerp(position().add(0,1.5,0),i/6.);particle(ParticleTypes.GLOW,p,(valves()&(1<<role))==0?2:1);}}if(a>=GuardianRules.HEAL_WARNING&&a%GuardianRules.HEAL_TICK==0&&GuardianRules.healAllowed(valves(),now,n.getLong("ValveBlockedUntil"))&&w.getBlockState(GuardianWorld.healingSource(n)).is(org.slavicmyths.sanctuary.SanctuaryContent.block("pure_spring_heart"))&&distanceToSqr(Vec3.atBottomCenterOf(net.minecraft.core.BlockPos.of(layout.getLong("SpawnAnchor"))))<=4)heal(GuardianRules.HEAL_AMOUNT);if(a>=GuardianRules.HEAL_WARNING+GuardianRules.HEAL_ACTIVE){healReady=now+GuardianRules.HEAL_COOLDOWN;state(GuardianRules.COMBAT);}return;}
  if(s==GuardianRules.COMBAT){if(getTarget()==null)return;if(!n.getBoolean("Standalone")&&getHealth()<getMaxHealth()*.8&&now>=healReady&&GuardianRules.healAllowed(valves(),now,n.getLong("ValveBlockedUntil"))){state(GuardianRules.SEEK);getTarget().sendSystemMessage(GuardianContent.text("healing_hint"));return;}if(now>=whirlReady){whirl=getTarget().position();entityData.set(WHIRL_AT,new org.joml.Vector3f((float)(whirl.x-origin().getX()),(float)(whirl.y-origin().getY()),(float)(whirl.z-origin().getZ())));state(GuardianRules.WHIRL);sound("spring_whirlpool_warning");return;}if(now>=prisonReady&&!getTarget().getUUID().equals(lastPrison)&&getTarget() instanceof ServerPlayer&&safePrison(getTarget())){prisonTarget=getTarget().getUUID();state(GuardianRules.PRISON);sound("spring_prison_form");return;}if(now>=floodReady){state(GuardianRules.FLOOD);sound("spring_flood_rise");return;}if(now>=whipReady){state(GuardianRules.WHIP);sound("spring_whip_windup");return;}melee();return;}
  if(s==GuardianRules.WHIP){if(getTarget()==null){whipReady=now+GuardianRules.WHIP_COOLDOWN;state(GuardianRules.COMBAT);return;}if(a==GuardianRules.WHIP_WINDUP||a==GuardianRules.WHIP_WINDUP+GuardianRules.WHIP_GAP){boolean second=a>GuardianRules.WHIP_WINDUP;sound("spring_whip_impact");for(var t:targets())if(arc(t,second)){hit(t,GuardianRules.WHIP_DAMAGE);t.knockback(.12,getX()-t.getX(),getZ()-t.getZ());}}if(a>=GuardianRules.WHIP_WINDUP+GuardianRules.WHIP_GAP+12){whipReady=now+(desperation()?110:GuardianRules.WHIP_COOLDOWN);state(GuardianRules.COMBAT);}return;}
  if(s==GuardianRules.WHIRL){if(a%4==0)ring(whirl,GuardianRules.WHIRL_RADIUS,a<=GuardianRules.WHIRL_WARNING?ParticleTypes.GLOW:ParticleTypes.BUBBLE);if(a==GuardianRules.WHIRL_WARNING)sound("spring_whirlpool_loop");if(a>GuardianRules.WHIRL_WARNING)for(var t:targets())if(t.position().distanceToSqr(whirl)<=6.25&&hasLineOfSight(t)){var pull=whirl.subtract(t.position()).multiply(1,0,1).normalize().scale(GuardianRules.WHIRL_PULL);t.setDeltaMovement(t.getDeltaMovement().add(pull));t.hurtMarked=true;if((a-GuardianRules.WHIRL_WARNING)%20==0)hit(t,GuardianRules.WHIRL_DAMAGE);}if(a>=GuardianRules.WHIRL_WARNING+GuardianRules.WHIRL_ACTIVE){whirlReady=now+GuardianRules.WHIRL_COOLDOWN;state(GuardianRules.COMBAT);}return;}
  if(s==GuardianRules.PRISON){var t=prisonTarget==null?null:w.getEntity(prisonTarget);if(t instanceof LivingEntity l&&candidate(l)&&a<GuardianRules.PRISON_WARNING&&a%4==0)ring(l.position(),1,ParticleTypes.GLOW);if(a==GuardianRules.PRISON_WARNING&&t instanceof ServerPlayer p&&candidate(p)&&safePrison(p)){prison=new WaterPrison(GuardianContent.PRISON.get(),w);prison.configure(this,p);w.addFreshEntity(prison);lastPrison=p.getUUID();}if(a>=GuardianRules.PRISON_WARNING+10){prisonReady=now+GuardianRules.PRISON_COOLDOWN;state(GuardianRules.COMBAT);}return;}
  if(s==GuardianRules.FLOOD){if(a%4==0){var regions=floodRegions();for(int region=0;region<regions.length;region++){var b=regions[region];int local=a-GuardianRules.floodDelay(region);double height=local<GuardianRules.FLOOD_WARNING?.05:Math.min(.8,(local-GuardianRules.FLOOD_WARNING)/25.);height=Math.min(height,Math.max(.05,(GuardianRules.FLOOD_WARNING+GuardianRules.FLOOD_ACTIVE-a)/30.));for(double x=b.minX+.5;x<b.maxX;x+=2)for(double z=b.minZ+.5;z<b.maxZ;z+=2)particle(local<GuardianRules.FLOOD_WARNING?ParticleTypes.GLOW:ParticleTypes.SPLASH,new Vec3(x,b.minY+height,z),1);}}if(a>GuardianRules.FLOOD_WARNING)for(var t:targets())if(floodDanger(t.getX(),t.getZ())&&floodRegion(t.position())>=0&&a>=GuardianRules.FLOOD_WARNING+GuardianRules.floodDelay(floodRegion(t.position()))){t.setDeltaMovement(t.getDeltaMovement().multiply(GuardianRules.FLOOD_DRAG,1,GuardianRules.FLOOD_DRAG));t.hurtMarked=true;}if(a>=GuardianRules.FLOOD_WARNING+GuardianRules.FLOOD_ACTIVE){floodReady=now+GuardianRules.FLOOD_COOLDOWN;state(GuardianRules.COMBAT);}return;}
 }
 public AABB[] floodRegions(){var regions=new AABB[2];for(int i=0;i<2;i++){var b=org.slavicmyths.sanctuary.SanctuaryGeometry.box(origin(),rotation(),72,1,i==0?13:24,86,1,i==0?17:27);regions[i]=new AABB(b.minX(),b.minY(),b.minZ(),b.maxX()+1,b.maxY()+1,b.maxZ()+1);}return regions;}
 public boolean floodDanger(double x,double z){var local=new Vec3(x-origin().getX(),0,z-origin().getZ()).yRot((float)Math.toRadians(switch(rotation()){case CLOCKWISE_90->90;case CLOCKWISE_180->180;case COUNTERCLOCKWISE_90->270;default->0;}));return local.z<18||local.z>=24;}
 private int floodRegion(Vec3 p){var areas=floodRegions();for(int i=0;i<areas.length;i++)if(areas[i].inflate(0,5,0).contains(p))return i;return -1;}
 private boolean arc(LivingEntity t,boolean second){Vec3 v=t.position().subtract(position());double length=v.horizontalDistance();if(length>6||length<.01||!hasLineOfSight(t))return false;double angle=Math.atan2(v.x,v.z)+Math.toRadians(getYRot()),center=Math.toRadians(second?-28:28);double diff=Math.atan2(Math.sin(angle-center),Math.cos(angle-center));return Math.abs(diff)<Math.toRadians(65);}
 private boolean safePrison(LivingEntity t){return arena().contains(t.position().add(-1,0,-1))&&arena().contains(t.position().add(1,2.7,1))&&level().noCollision(t,t.getBoundingBox().inflate(.6,.1,.6));}
 private void valves(CompoundTag n,long now){var w=(ServerLevel)level();var d=GuardianLedger.get(w);if(n.getInt("Valves")==3&&now>=n.getLong("ValveBlockedUntil")){n.putInt("Valves",0);d.setDirty();GuardianWorld.install(w,instance,n);}
  for(int role=0;role<2;role++){String key="PendingValve"+role;var action=n.getCompound(key);if(!action.hasUUID("Player")||now<action.getLong("At"))continue;n.remove(key);var p=w.getServer().getPlayerList().getPlayer(action.getUUID("Player"));var at=GuardianWorld.valveAt(n,role);if(p==null||p.level()!=w||!p.isAlive()||p.isSpectator()||p.distanceToSqr(Vec3.atCenterOf(at))>25||!w.mayInteract(p,at)||p.server.isUnderSpawnProtection(w,at,p))continue;int mask=n.getInt("Valves")|(1<<role);n.putInt("Valves",mask);d.setDirty();credit(p);GuardianContent.sound(w,at,"spring_valve_switch");if(mask==3){n.putLong("ValveBlockedUntil",now+GuardianRules.HEAL_BLOCK);healReady=now+GuardianRules.HEAL_BLOCK;state(GuardianRules.INTERRUPTED);sound("spring_heal_interrupt");}GuardianWorld.install(w,instance,n);}
  entityData.set(VALVES,n.getInt("Valves"));
 }
 public void prisonHit(ServerPlayer p){if(prison!=null&&prison.isAlive()&&p.getUUID().equals(prison.target))prison.action(p);}
 @Override protected void clearHazards(){if(prison!=null){prison.discard();prison=null;}if(level() instanceof ServerLevel w){for(UUID id:echoes){var e=w.getEntity(id);if(e!=null)e.discard();}echoes.clear();if(instance!=null){var n=GuardianLedger.get(w).row(instance);n.remove("PendingValve0");n.remove("PendingValve1");n.putInt("Valves",state()==GuardianRules.CLEANSED?3:0);n.remove("ValveBlockedUntil");}}}
}
